import React from 'react';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell,
  BarChart, Bar
} from 'recharts';

const enrollmentData = [
  { month: 'Jan', students: 400 }, { month: 'Feb', students: 600 }, { month: 'Mar', students: 800 },
  { month: 'Apr', students: 750 }, { month: 'May', students: 1000 }, { month: 'Jun', students: 1250 },
];

const subjectData = [
  { name: 'Science', value: 450 }, { name: 'Maths', value: 350 }, { name: 'English', value: 250 }, { name: 'IT', value: 200 },
];

const classDistributionData = [
  { grade: 'Grade 10', classes: 12 }, { grade: 'Grade 11', classes: 15 }, { grade: 'A/L 2026', classes: 10 }, { grade: 'A/L 2027', classes: 8 },
];

const THEME_COLORS = ['#15803d', '#22c55e', '#1e293b', '#64748b'];

const weeklySchedule = [
  { time: "08:00 AM", mon: "O/L Science", tue: "-", wed: "O/L Science", thu: "-", fri: "Revision", sat: "O/L Maths", sun: "-" },
  { time: "10:30 AM", mon: "-", tue: "A/L Physics", wed: "-", thu: "A/L Physics", fri: "-", sat: "A/L Chem", sun: "A/L Physics" },
  { time: "01:00 PM", mon: "O/L Maths", tue: "-", wed: "O/L Maths", thu: "-", fri: "Paper Class", sat: "-", sun: "A/L Chem" },
  { time: "03:30 PM", mon: "-", tue: "A/L Chem", wed: "-", thu: "A/L Chem", fri: "-", sat: "English Lit", sun: "-" },
];

export default function DashboardOverview() {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', height: '100%' }}>
      
      {/* Stat Cards Row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '15px', flexShrink: 0 }}>
        <StatCard title="Total Students" value="1,250" accentColor="#15803d" icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#15803d" strokeWidth="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle></svg>} />
        <StatCard title="Total Teachers" value="24" accentColor="#22c55e" icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#22c55e" strokeWidth="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"></path><path d="M6.5 2H20v20H6.5z"></path></svg>} />
        <StatCard title="Active Classes" value="45" accentColor="#1e293b" icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#1e293b" strokeWidth="2"><rect x="3" y="4" width="18" height="18" rx="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line></svg>} />
        <StatCard title="Today's Classes" value="08" accentColor="#64748b" icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>} />
      </div>

      {/* Graphs Section - උස 160px කර තනි screen එකකට ලස්සනට සෙට් කළා */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px', flexShrink: 0 }}>
        
        {/* Enrollment */}
        <div style={{ backgroundColor: '#fff', padding: '12px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)' }}>
          <h4 style={{ marginTop: 0, color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', fontSize: '14px' }}>Enrollment Growth</h4>
          <div style={{ width: '100%', height: '160px', marginTop: '10px' }}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={enrollmentData} margin={{ left: -25, right: 10 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="month" /><YAxis /><Tooltip /><Line type="monotone" dataKey="students" stroke="#15803d" strokeWidth={2.5} dot={{ r: 3 }} /></LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Class Distribution */}
        <div style={{ backgroundColor: '#fff', padding: '12px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)' }}>
          <h4 style={{ marginTop: 0, color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', fontSize: '14px' }}>Class Distribution</h4>
          <div style={{ width: '100%', height: '160px', marginTop: '10px' }}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={classDistributionData} margin={{ left: -25, right: 10 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="grade" /><YAxis /><Tooltip /><Bar dataKey="classes" fill="#22c55e" radius={[4, 4, 0, 0]} barSize={22} /></BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Pie Chart */}
        <div style={{ backgroundColor: '#fff', padding: '12px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)', display: 'flex', flexDirection: 'column' }}>
          <h4 style={{ marginTop: 0, color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', fontSize: '14px' }}>Students by Subject</h4>
          <div style={{ flex: 1, minHeight: '120px' }}>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart><Pie data={subjectData} cx="50%" cy="50%" innerRadius={35} outerRadius={50} paddingAngle={4} dataKey="value">{subjectData.map((entry, index) => <Cell key={index} fill={THEME_COLORS[index % THEME_COLORS.length]} />)}</Pie><Tooltip /></PieChart>
            </ResponsiveContainer>
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', gap: '8px', flexWrap: 'wrap' }}>
            {subjectData.map((entry, index) => <div key={index} style={{ display: 'flex', alignItems: 'center', fontSize: '10px', color: '#64748b' }}><div style={{ width: '6px', height: '6px', backgroundColor: THEME_COLORS[index], borderRadius: '50%', marginRight: '3px' }}></div>{entry.name}</div>)}
          </div>
        </div>

      </div>

      {/* Upcoming Class Schedule Table - කිසිසේත්ම scroll නොවෙන කුඩා ටේබල් එක */}
      <div style={{ backgroundColor: '#fff', padding: '12px 18px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)', flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
        <h3 style={{ marginTop: 0, color: '#15803d', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', marginBottom: '8px', fontSize: '14px' }}>Upcoming Class Schedule</h3>
        <div style={{ overflowX: 'auto', width: '100%', flex: 1 }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', border: '1px solid #cbd5e1' }}>
            <thead>
              <tr style={{ backgroundColor: '#f8fafc' }}>
                <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', border: '1px solid #cbd5e1' }}>Time</th>
                <th style={{ padding: '6px 8px', border: '1px solid #cbd5e1' }}>Mon</th><th style={{ padding: '6px 8px', border: '1px solid #cbd5e1' }}>Tue</th><th style={{ padding: '6px 8px', border: '1px solid #cbd5e1' }}>Wed</th><th style={{ padding: '6px 8px', border: '1px solid #cbd5e1' }}>Thu</th><th style={{ padding: '6px 8px', border: '1px solid #cbd5e1' }}>Fri</th><th style={{ padding: '6px 8px', border: '1px solid #cbd5e1' }}>Sat</th><th style={{ padding: '6px 8px', border: '1px solid #cbd5e1' }}>Sun</th>
              </tr>
            </thead>
            <tbody>
              {weeklySchedule.map((row, index) => (
                <tr key={index}>
                  <td style={{ padding: '4px 8px', fontSize: '11px', fontWeight: '700', backgroundColor: '#f8fafc', border: '1px solid #cbd5e1', textAlign: 'left' }}>{row.time}</td>
                  <td style={{ border: '1px solid #cbd5e1' }}><ScheduleCell text={row.mon} /></td>
                  <td style={{ border: '1px solid #cbd5e1' }}><ScheduleCell text={row.tue} /></td>
                  <td style={{ border: '1px solid #cbd5e1' }}><ScheduleCell text={row.wed} /></td>
                  <td style={{ border: '1px solid #cbd5e1' }}><ScheduleCell text={row.thu} /></td>
                  <td style={{ border: '1px solid #cbd5e1' }}><ScheduleCell text={row.fri} /></td>
                  <td style={{ border: '1px solid #cbd5e1' }}><ScheduleCell text={row.sat} /></td>
                  <td style={{ border: '1px solid #cbd5e1' }}><ScheduleCell text={row.sun} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}

function ScheduleCell({ text }) {
  if (text === "-") return <span style={{ color: '#94a3b8', fontSize: '10px' }}>-</span>;
  let bgColor = '#e0f2fe'; let textColor = '#0369a1';
  if (text.includes("Science")) { bgColor = '#dcfce7'; textColor = '#15803d'; }
  else if (text.includes("Maths")) { bgColor = '#fef9c3'; textColor = '#a16207'; }
  else if (text.includes("Physics")) { bgColor = '#f3e8ff'; textColor = '#6b21a8'; }
  else if (text.includes("Class") || text.includes("Revision")) { bgColor = '#fee2e2'; textColor = '#991b1b'; }

  return <span style={{ backgroundColor: bgColor, color: textColor, padding: '2px 5px', borderRadius: '4px', fontWeight: '600', fontSize: '10px', display: 'inline-block', minWidth: '78px' }}>{text}</span>;
}

function StatCard({ title, value, accentColor, icon }) {
  return (
    <div style={{ backgroundColor: '#fff', padding: '15px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)', borderLeft: `5px solid ${accentColor}`, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
      <div>
        <p style={{ margin: 0, color: '#64748b', fontSize: '13px' }}>{title}</p>
        <h2 style={{ margin: '5px 0 0 0', color: '#1e293b', fontSize: '24px' }}>{value}</h2>
      </div>
      <div>{icon}</div>
    </div>
  );
}
